// IsValid 校验值是否属于枚举合法集合。
func IsValid(enumName, val string) bool {
	allowed, ok := Allowed[enumName]
	if !ok {
		return false
	}
	for _, v := range strings.Split(allowed, "|") {
		if v == val {
			return true
		}
	}
	return false
}

// OneOfTag 返回 validator 的 oneof 校验 tag（如 oneof=PENDING QUEUED）。
func OneOfTag(enumName string) string {
	allowed, ok := Allowed[enumName]
	if !ok {
		return ""
	}
	return "oneof=" + strings.ReplaceAll(allowed, "|", " ")
}
